{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Comparison of feature profiles between Brás and the most similar Chicago areas",
  "params": [
    {
      "name": "clickSelect",
      "select": "interval"
    }
  ],
  "transform": [
    {
      "fold": [
        "poverty_rate",
        "unemployment_rate",
        "median_income",
        "edu_low",
        "minority_pct",
        "housing_burden",
        "crash_rate",
        "pop_density",
        "transit_access",
        "access_score"
      ],
      "as": ["Feature", "Value"]
    }
  ],
  "mark": {
    "type": "point",
    "cursor": "pointer",
    "size": 100
  },
  "encoding": {
    "x": {
      "field": "Feature",
      "type": "nominal",
      "axis": {"labelAngle": -45}
    },
    "y": {
      "field": "Value",
      "type": "quantitative"
    },
    "color": {
      "field": "area_name",
      "type": "nominal",
      "scale": {"scheme": "category10"}
    },
    "opacity": {
      "condition": {"param": "clickSelect", "value": 1},
      "value": 0.3
    },
    "shape": {
      "condition": {
        "test": "datum.area_name === 'Brás'",
        "value": "diamond"
      },
      "value": "circle"
    }
  }
}

import geopandas as gpd

gdf = arg

# Ensure the GeoDataFrame is in the required CRS 3395 for AUTK_MAP
if gdf.crs is not None:
    gdf = gdf.to_crs(epsg=3395)
else:
    gdf = gdf.set_crs(epsg=4326).to_crs(epsg=3395)

# The 'interacted' column is used by the system for highlighting/selection via DATA_POOL
# We ensure it exists to enable visual feedback on the map
if 'interacted' not in gdf.columns:
    gdf['interacted'] = 0

# Annotate metadata so AUTK_MAP recognizes the layer name
gdf.metadata = {
   'name': 'chicago_similarity_map'
}

return gdf
